2|/*
3| * Currently ecp_mul() takes a RNG function as an argument, used for
4| * side-channel protection, but it can be NULL. The initial reasoning was
5| * that people will pass non-NULL RNG when they care about side-channels, but
6| * unfortunately we have some APIs that call ecp_mul() with a NULL RNG, with
7| * no opportunity for the user to do anything about it.
8| *
9| * The obvious strategies for addressing that include:
10| * - change those APIs so that they take RNG arguments;
11| * - require a global RNG to be available to all crypto modules.
12| *
13| * Unfortunately those would break compatibility. So what we do instead is
14| * have our own internal DRBG instance, seeded from the secret scalar.
15| *
16| * The following is a light-weight abstraction layer for doing that with
17| * HMAC_DRBG (first choice) or CTR_DRBG.
18| */
19|
20|#if defined(MBEDTLS_HMAC_DRBG_C)
21|
22|/* DRBG context type */
23|typedef mbedtls_hmac_drbg_context ecp_drbg_context;
24|
25|/* DRBG context init */
26|static inline void ecp_drbg_init( ecp_drbg_context *ctx )
27|{
28|    mbedtls_hmac_drbg_init( ctx );
29|}
30|
31|/* DRBG context free */
32|static inline void ecp_drbg_free( ecp_drbg_context *ctx )
33|{
34|    mbedtls_hmac_drbg_free( ctx );
35|}
36|
37|/* DRBG function */
38|static inline int ecp_drbg_random( void *p_rng,
39|                                   unsigned char *output, size_t output_len )
40|{
41|    return( mbedtls_hmac_drbg_random( p_rng, output, output_len ) );
42|}
