44|/* DRBG context seeding */
45|static int ecp_drbg_seed( ecp_drbg_context *ctx,
46|                   const mbedtls_mpi *secret, size_t secret_len )
47|{
48|    int ret;
49|    unsigned char secret_bytes[MBEDTLS_ECP_MAX_BYTES];
50|    /* The list starts with strong hashes */
51|    const mbedtls_md_type_t md_type = mbedtls_md_list()[0];
52|    const mbedtls_md_info_t *md_info = mbedtls_md_info_from_type( md_type );
53|
54|    if( secret_len > MBEDTLS_ECP_MAX_BYTES )
55|    {
56|        ret = MBEDTLS_ERR_ECP_RANDOM_FAILED;
57|        goto cleanup;
58|    }
59|
60|    MBEDTLS_MPI_CHK( mbedtls_mpi_write_binary( secret,
61|                                               secret_bytes, secret_len ) );
62|
63|    ret = mbedtls_hmac_drbg_seed_buf( ctx, md_info, secret_bytes, secret_len );
64|
65|cleanup:
66|    mbedtls_platform_zeroize( secret_bytes, secret_len );
67|
68|    return( ret );
69|}
