95|/*
96| * Since CTR_DRBG doesn't have a seed_buf() function the way HMAC_DRBG does,
97| * we need to pass an entropy function when seeding. So we use a dummy
98| * function for that, and pass the actual entropy as customisation string.
99| * (During seeding of CTR_DRBG the entropy input and customisation string are
100| * concatenated before being used to update the secret state.)
101| */
102|static int ecp_ctr_drbg_null_entropy(void *ctx, unsigned char *out, size_t len)
103|{
104|    (void) ctx;
105|    memset( out, 0, len );
106|    return( 0 );
107|}
