109|/* DRBG context seeding */
110|static int ecp_drbg_seed( ecp_drbg_context *ctx,
111|                   const mbedtls_mpi *secret, size_t secret_len )
112|{
113|    int ret;
114|    unsigned char secret_bytes[MBEDTLS_ECP_MAX_BYTES];
115|
116|    if( secret_len > MBEDTLS_ECP_MAX_BYTES )
117|    {
118|        ret = MBEDTLS_ERR_ECP_RANDOM_FAILED;
119|        goto cleanup;
120|    }
121|
122|    MBEDTLS_MPI_CHK( mbedtls_mpi_write_binary( secret,
123|                                               secret_bytes, secret_len ) );
124|
125|    ret = mbedtls_ctr_drbg_seed( ctx, ecp_ctr_drbg_null_entropy, NULL,
126|                                 secret_bytes, secret_len );
127|
128|cleanup:
129|    mbedtls_platform_zeroize( secret_bytes, secret_len );
130|
131|    return( ret );
132|}
