380|    /*
381|     * Don't use any blinding the first time a particular X is used,
382|     * but remember it to use blinding next time.
383|     */
384|    if( mbedtls_mpi_cmp_mpi( &ctx->X, &ctx->pX ) != 0 )
385|    {
386|        MBEDTLS_MPI_CHK( mbedtls_mpi_copy( &ctx->pX, &ctx->X ) );
