987|static int ecjpake_lgc( void *p, unsigned char *out, size_t len )
988|{
989|    static uint32_t x = 42;
990|    (void) p;
991|
992|    while( len > 0 )
993|    {
994|        size_t use_len = len > 4 ? 4 : len;
995|        x = 1664525 * x + 1013904223;
996|        memcpy( out, &x, use_len );
997|        out += use_len;
998|        len -= use_len;
999|    }
1000|
1001|    return( 0 );
