3321|static int self_test_adjust_exponent( const mbedtls_ecp_group *grp,
3322|                                      mbedtls_mpi *m )
3323|{
3324|    int ret = 0;
3325|    switch( grp->id )
3326|    {
3327|        /* If Curve25519 is available, then that's what we use for the
3328|         * Montgomery test, so we don't need the adjustment code. */
3329|#if ! defined(MBEDTLS_ECP_DP_CURVE25519_ENABLED)
3330|#if defined(MBEDTLS_ECP_DP_CURVE448_ENABLED)
3331|        case MBEDTLS_ECP_DP_CURVE448:
