3333|             * necessary to enforce the highest-bit-set constraint. */
3334|            MBEDTLS_MPI_CHK( mbedtls_mpi_set_bit( m, 254, 0 ) );
3335|            MBEDTLS_MPI_CHK( mbedtls_mpi_set_bit( m, grp->nbits, 1 ) );
