3337|             * necessary but improves the test variety a bit. */
3338|            MBEDTLS_MPI_CHK(
3339|                mbedtls_mpi_set_bit( m, grp->nbits - 1,
3340|                                     mbedtls_mpi_get_bit( m, 253 ) ) );
3341|            break;
3342|#endif
3343|#endif /* ! defined(MBEDTLS_ECP_DP_CURVE25519_ENABLED) */
3344|        default:
3345|            /* Non-Montgomery curves and Curve25519 need no adjustment. */
3346|            (void) grp;
3347|            (void) m;
3348|            goto cleanup;
3349|    }
