503|int mbedtls_pk_check_pair( const mbedtls_pk_context *pub, const mbedtls_pk_context *prv )
504|{
505|    PK_VALIDATE_RET( pub != NULL );
506|    PK_VALIDATE_RET( prv != NULL );
507|
508|    if( pub->pk_info == NULL ||
509|        prv->pk_info == NULL )
510|    {
511|        return( MBEDTLS_ERR_PK_BAD_INPUT_DATA );
512|    }
513|
514|    if( prv->pk_info->check_pair_func == NULL )
515|        return( MBEDTLS_ERR_PK_FEATURE_UNAVAILABLE );
516|
517|    if( prv->pk_info->type == MBEDTLS_PK_RSA_ALT )
518|    {
519|        if( pub->pk_info->type != MBEDTLS_PK_RSA )
520|            return( MBEDTLS_ERR_PK_TYPE_MISMATCH );
521|    }
522|    else
523|    {
524|        if( pub->pk_info != prv->pk_info )
525|            return( MBEDTLS_ERR_PK_TYPE_MISMATCH );
526|    }
527|
528|    return( prv->pk_info->check_pair_func( pub->pk_ctx, prv->pk_ctx ) );
529|}

