861|static int pk_parse_key_sec1_der( mbedtls_ecp_keypair *eck,
862|                                  const unsigned char *key,
863|                                  size_t keylen )
864|{
865|    int ret = MBEDTLS_ERR_ERROR_CORRUPTION_DETECTED;
866|    int version, pubkey_done;
867|    size_t len;
868|    mbedtls_asn1_buf params;
869|    unsigned char *p = (unsigned char *) key;
870|    unsigned char *end = p + keylen;
871|    unsigned char *end2;
872|
873|    /*
874|     * RFC 5915, or SEC1 Appendix C.4
875|     *
876|     * ECPrivateKey ::= SEQUENCE {
877|     *      version        INTEGER { ecPrivkeyVer1(1) } (ecPrivkeyVer1),
878|     *      privateKey     OCTET STRING,
879|     *      parameters [0] ECParameters {{ NamedCurve }} OPTIONAL,
880|     *      publicKey  [1] BIT STRING OPTIONAL
881|     *    }
882|     */
883|    if( ( ret = mbedtls_asn1_get_tag( &p, end, &len,
884|            MBEDTLS_ASN1_CONSTRUCTED | MBEDTLS_ASN1_SEQUENCE ) ) != 0 )
885|    {
886|        return( MBEDTLS_ERROR_ADD( MBEDTLS_ERR_PK_KEY_INVALID_FORMAT, ret ) );
887|    }
888|
889|    end = p + len;
890|
891|    if( ( ret = mbedtls_asn1_get_int( &p, end, &version ) ) != 0 )
892|        return( MBEDTLS_ERROR_ADD( MBEDTLS_ERR_PK_KEY_INVALID_FORMAT, ret ) );
893|
894|    if( version != 1 )
895|        return( MBEDTLS_ERR_PK_KEY_INVALID_VERSION );
896|
897|    if( ( ret = mbedtls_asn1_get_tag( &p, end, &len, MBEDTLS_ASN1_OCTET_STRING ) ) != 0 )
898|        return( MBEDTLS_ERROR_ADD( MBEDTLS_ERR_PK_KEY_INVALID_FORMAT, ret ) );
899|
900|    if( ( ret = mbedtls_mpi_read_binary( &eck->d, p, len ) ) != 0 )
901|    {
902|        mbedtls_ecp_keypair_free( eck );
903|        return( MBEDTLS_ERROR_ADD( MBEDTLS_ERR_PK_KEY_INVALID_FORMAT, ret ) );
904|    }
905|
906|    p += len;
907|
908|    pubkey_done = 0;
909|    if( p != end )
910|    {
911|        /*
912|         * Is 'parameters' present?
913|         */
914|        if( ( ret = mbedtls_asn1_get_tag( &p, end, &len,
915|                        MBEDTLS_ASN1_CONTEXT_SPECIFIC | MBEDTLS_ASN1_CONSTRUCTED | 0 ) ) == 0 )
916|        {
917|            if( ( ret = pk_get_ecparams( &p, p + len, &params) ) != 0 ||
918|                ( ret = pk_use_ecparams( &params, &eck->grp )  ) != 0 )
919|            {
920|                mbedtls_ecp_keypair_free( eck );
921|                return( ret );
922|            }
923|        }
924|        else if( ret != MBEDTLS_ERR_ASN1_UNEXPECTED_TAG )
925|        {
926|            mbedtls_ecp_keypair_free( eck );
927|            return( MBEDTLS_ERROR_ADD( MBEDTLS_ERR_PK_KEY_INVALID_FORMAT, ret ) );
928|        }
929|    }
930|
931|    if( p != end )
932|    {
933|        /*
934|         * Is 'publickey' present? If not, or if we can't read it (eg because it
935|         * is compressed), create it from the private key.
936|         */
937|        if( ( ret = mbedtls_asn1_get_tag( &p, end, &len,
938|                        MBEDTLS_ASN1_CONTEXT_SPECIFIC | MBEDTLS_ASN1_CONSTRUCTED | 1 ) ) == 0 )
939|        {
